SELECT m.BATCH_SEQ AS batchSeq, m.TRADE_MARKET AS tradeMarket, t1.secAcctId, t1.secAcctName, t2.ps AS ps, t3.termType AS termType, m.FEE_TYPE AS feeType, m.TRADE_TYPE AS tradeType, m.CHARGE_TYPE AS chargeType, m.EFF_DATE as effDate, m.CHARGE_BASIS as chargeBasis, m.FEE_MAXI as feeMaxi, m.FEE_MINI as feeMini, case when m.CHARGE_TYPE='01' then m.CHARGE_RATE * 1000 else m.CHARGE_VALUE end as chargeValue, m.CHARGE_RATE as chargeRate, m.IS_PAY_WITH_TRADE as isPayWithTrade FROM ( select BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE ,t.IS_PAY_WITH_TRADE from TRD_FEE_CONFIG t inner join TRD_FEE_CONFIG_DETAIL t1 on t.SEQ_NO=t1.CONFIG_SEQ_NO where t.FEE_TYPE IN('B02','B05') GROUP BY t.BATCH_SEQ,TRADE_MARKET , FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE,t.IS_PAY_WITH_TRADE ) m INNER JOIN ( select n.BATCH_SEQ,
/*regexp_replace(group_concat( n.sec_acct_id order by (n.sec_acct_id) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') secAcctId ,*/ group_concat(distinct n.sec_acct_id order by (n.sec_acct_id) separator ',') secAcctId , /*wm_concat(DISTINCT n1.sec_acct_name)as secAcctName from TRD_FEE_CONFIG n*/ group_concat(DISTINCT n1.sec_acct_name order by (n1.sec_acct_name) separator ',') as secAcctName from TRD_FEE_CONFIG n left join STL_SEC_ACCT_INFO n1 on n.SEC_ACCT_ID=n1.SEC_ACCT_ID where n.FEE_TYPE IN('B02','B05') GROUP BY n.BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t1 on m.BATCH_SEQ=t1.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
/*regexp_replace(group_concat( ps order by (ps) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') ps*/ group_concat(distinct ps order by (ps) separator ',') ps from TRD_FEE_CONFIG where FEE_TYPE IN('B02','B05') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t2 on m.BATCH_SEQ=t2.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
/*regexp_replace(group_concat( TERM_TYPE order by (TERM_TYPE) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') termType*/ group_concat(distinct TERM_TYPE order by (TERM_TYPE) separator ',') termType from TRD_FEE_CONFIG where FEE_TYPE IN('B02','B05') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t3 on m.BATCH_SEQ=t3.BATCH_SEQ
m.FEE_TYPE=#{feeType,jdbcType=VARCHAR}
and m.TRADE_MARKET = #{tradeMarket}
order by m.BATCH_SEQ,m.EFF_DATE desc

SELECT m.BATCH_SEQ AS batchSeq, m.TRADE_MARKET AS tradeMarket, t1.secAcctId, t2.ps AS ps, t3.termType AS termType, m.FEE_TYPE AS feeType, m.TRADE_TYPE AS tradeType, m.CHARGE_TYPE AS chargeType, m.EFF_DATE as effDate, m.CHARGE_BASIS as chargeBasis, m.FEE_MAXI as feeMaxi, m.FEE_MINI as feeMini, m.CHARGE_VALUE as chargeValue, m.CHARGE_RATE * 1000 as chargeRate, m.IS_PAY_WITH_TRADE as isPayWithTrade FROM ( select BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE,t.IS_PAY_WITH_TRADE from TRD_FEE_CONFIG t inner join TRD_FEE_CONFIG_DETAIL t1 on t.SEQ_NO=t1.CONFIG_SEQ_NO where t.FEE_TYPE IN('B02','B05') GROUP BY t.BATCH_SEQ,TRADE_MARKET , FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE,t.IS_PAY_WITH_TRADE ) m INNER JOIN ( select n.BATCH_SEQ,
/*regexp_replace(group_concat( n.sec_acct_id order by (n.sec_acct_id) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') secAcctId*/ group_concat(distinct n.sec_acct_id order by (n.sec_acct_id) separator ',') secAcctId from TRD_FEE_CONFIG n where n.FEE_TYPE IN('B02','B05') GROUP BY n.BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t1 on m.BATCH_SEQ=t1.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
/*regexp_replace(group_concat( ps order by (ps) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') ps*/ group_concat(distinct ps order by (ps) separator ',') ps from TRD_FEE_CONFIG where FEE_TYPE IN('B02','B05') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t2 on m.BATCH_SEQ=t2.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
/*regexp_replace(group_concat( TERM_TYPE order by (TERM_TYPE) separator ',') ,'([^,]+)(,\1)*(,|$)','\1\3') termType*/ group_concat(distinct TERM_TYPE order by (TERM_TYPE) separator ',') termType from TRD_FEE_CONFIG where FEE_TYPE IN('B02','B05') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t3 on m.BATCH_SEQ=t3.BATCH_SEQ where m.BATCH_SEQ = #{batchSeq,jdbcType=VARCHAR}

SELECT
    count(1)
 FROM TRD_FEE_CONFIG m
 where 
 m.ps = #{ps,jdbcType=VARCHAR}
 and m.TRADE_TYPE = #{tradeType,jdbcType=VARCHAR}
 and m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
 and m.EFF_DATE = STR_TO_DATE(#{effDate,jdbcType=VARCHAR},'%Y-%m-%d %H:%i:%s')

 and m.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}


	 and  BATCH_SEQ <> #{batchSeq}


	and m.TERM_TYPE = #{termType,jdbcType=VARCHAR}


	and m.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
